cd "$ARCHON_HORIZON_ROOT/.archon-horizon/roadmap" && ls | head; python3 - <<'EOF'
import json,glob
for p in sorted(glob.glob('/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/roadmap/*')):
    try: d=json.load(open(p))
    except Exception as e: print(p,'ERR',e); continue
    items = d if isinstance(d,list) else d.get('items',[])
    for it in items:
        if isinstance(it,dict) and str(it.get('id','')).startswith('AJC.fbc'):
            print(it['id'],'|',it.get('status'),'|',it.get('owner'),'|',(it.get('title') or '')[:70])
EOF
